import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { bytesToHex } from '@noble/hashes/utils.js';
import { sha256 } from '@noble/hashes/sha2.js';
import { describe, expect, it } from 'vitest';

import { checkPhrase, deriveAccounts, hdPaths, normalizeWords, taprootAddress, taprootOutputKey, wordsToSeed } from './vaultHdWallet';

// The shared acceptance corpus, generated by a second implementation (Python bip_utils + embit) and
// owned by the backend lane (tests/fixtures/vault_signing/hd-seed-corpus.json). Public, never-funded
// test material: every address here is checked against this browser's own derivation.
type CorpusAccount = {
  account: number; eth: string; btc_taproot: string; btc_taproot_testnet: string; solana: string;
  bitcoin_output_key: string; paths: { evm: string; bitcoin: string; solana: string };
  public_keys: { bitcoin: string };
};
type CorpusEntry = { id: string; words: string; passphrase: string; seed_hex: string; seed_sha256: string; accounts: CorpusAccount[] };
const corpusPath = process.env.VAULT_HD_CORPUS ?? resolve(__dirname, '../../../tests/fixtures/vault_signing/hd-seed-corpus.json');
const corpus = JSON.parse(readFileSync(corpusPath, 'utf8')) as { entries: CorpusEntry[] };

describe('seed-phrase wallet derivation against the independent corpus', () => {
  it('covers the agreed strata', () => {
    expect(corpus.entries.length).toBeGreaterThanOrEqual(37);
    expect(corpus.entries.some((e) => e.passphrase)).toBe(true);
    expect(corpus.entries.some((e) => e.words.split(' ').length === 24)).toBe(true);
    for (const entry of corpus.entries) expect(entry.accounts).toHaveLength(20);
  });

  it.each(corpus.entries.map((e) => [e.id, e] as const))('%s: words → seed → 20 accounts × 3 chains', (_id, entry) => {
    const check = checkPhrase(entry.words);
    expect(check.ok).toBe(true);
    const seed = wordsToSeed(normalizeWords(entry.words), entry.passphrase);
    expect(bytesToHex(seed)).toBe(entry.seed_hex);
    expect(bytesToHex(sha256(seed))).toBe(entry.seed_sha256);
    const derived = deriveAccounts(seed, 20);
    for (const [i, expected] of entry.accounts.entries()) {
      const got = derived[i];
      expect(got.account).toBe(expected.account);
      expect(got.paths).toEqual(expected.paths);
      expect(got.eth).toBe(expected.eth);
      expect(got.btc_taproot).toBe(expected.btc_taproot);
      expect(got.solana).toBe(expected.solana);
      // Same script on a test network: the testnet4 round trip spends exactly this output key.
      const outputKey = taprootOutputKey(Uint8Array.from(Buffer.from(expected.public_keys.bitcoin, 'hex')));
      expect(bytesToHex(outputKey)).toBe(expected.bitcoin_output_key);
      expect(taprootAddress(outputKey, 'testnet')).toBe(expected.btc_taproot_testnet);
    }
  });
});

describe('phrase checks', () => {
  const valid = 'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about';
  it('accepts a valid phrase with extra spaces and capitals, as words', () => {
    expect(checkPhrase(`  ${valid.toUpperCase().replace(/ /g, '   ')}\n`)).toEqual({ ok: true, words: valid.split(' ') });
  });
  it('names the first unknown word and suggests list words', () => {
    const check = checkPhrase(valid.replace('about', 'abuot'));
    expect(check).toMatchObject({ ok: false, reason: 'unknown-word', position: 12, word: 'abuot' });
    expect(check.ok === false && check.reason === 'unknown-word' && check.suggestions.every((w) => w.startsWith('ab'))).toBe(true);
  });
  it('refuses a bad checksum and a wrong length', () => {
    expect(checkPhrase(valid.replace('about', 'abandon'))).toEqual({ ok: false, reason: 'checksum' });
    expect(checkPhrase('abandon abandon abandon')).toEqual({ ok: false, reason: 'count', count: 3 });
    expect(checkPhrase('   ')).toEqual({ ok: false, reason: 'empty' });
  });
  it('NFKD-normalises the passphrase, so a composed and a decomposed form give one seed', () => {
    const words = valid.split(' ');
    expect(bytesToHex(wordsToSeed(words, 'caf\u00e9'))).toBe(bytesToHex(wordsToSeed(words, 'cafe\u0301')));
    expect(hdPaths(3).solana).toBe("m/44'/501'/3'/0'");
  });
});
